import {config,configured} from './cms-api.js';
export function attachChat(root,{mood,stopSpeech,endTour}){
 const $=id=>root.querySelector('#'+id),panel=$('g-panel');
 const area=document.createElement('div');area.id='g-conversation';area.hidden=true;
 area.innerHTML=`<p class="g-disclosure">AI answers use public portfolio information and may be imperfect. Messages you send go to Groq. Don’t share sensitive information.</p><div id="g-messages" role="log" aria-label="Conversation" aria-live="polite"></div><form id="g-chat-form"><label for="g-question">What would you like to know?</label><textarea id="g-question" maxlength="1200" rows="2" placeholder="Ask about a project, or tell me what you have in mind…" required></textarea><div class="g-actions"><button type="submit" class="g-primary" id="g-send">Send ↗</button><button type="button" id="g-cancel" hidden>Stop</button><button type="button" id="g-clear">Clear chat</button></div></form><p id="g-chat-status" role="status"></p>`;
 const requestArea=document.createElement('div');requestArea.id='g-request';requestArea.hidden=true;
 requestArea.innerHTML=`<p class="g-copy">Got something in mind? Leave Taher a request. You’ll review it before sending.</p><form id="g-request-form"><label>Your name<input name="name" maxlength="100" autocomplete="name" required></label><label>Your email<input name="email" type="email" maxlength="254" autocomplete="email" required></label><label>What’s it about?<select name="category"><option value="project">A project</option><option value="opportunity">An opportunity</option><option value="collaboration">A collaboration</option><option value="question">A question</option></select></label><label>Subject<input name="subject" maxlength="160" required></label><label>Your message<textarea name="message" minlength="10" maxlength="3000" rows="4" required></textarea></label><label class="g-trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="g-disclosure">Your name, email and message will be stored privately for Taher to review. Your chat transcript is not attached. To request removal, contact Taher using the portfolio email.</p><button type="submit" class="g-primary">Review request →</button></form><section id="g-review" hidden><h3>Check before sending</h3><div id="g-review-text"></div><label><input id="g-consent" type="checkbox"> I agree to send these details to Taher.</label><div class="g-actions"><button type="button" id="g-confirm" class="g-primary">Confirm & send</button><button type="button" id="g-edit">Edit</button></div></section><p id="g-request-status" role="status"></p>`;
 const nav=document.createElement('div');nav.className='g-chat-nav';
 for(const [id,text] of [['g-tour-tab','Tour'],['g-chat-tab','Chat'],['g-request-tab','Leave a request']]){const b=document.createElement('button');b.type='button';b.id=id;b.textContent=text;nav.append(b);}
 panel.querySelector('.g-head').after(nav);panel.querySelector('.g-foot').before(area,requestArea);
 const tourElements=['g-copy','g-status'];let mode='tour',history=[],controller=null,busy=false,review=null,requestID=null,sending=false;
 function switchMode(next){if(next!==mode)controller?.abort();stopSpeech();endTour();mode=next;area.hidden=next!=='chat';requestArea.hidden=next!=='request';root.classList.toggle('g-chat-mode',next!=='tour');for(const id of tourElements)$(id).hidden=next!=='tour';$('g-start').closest('.g-actions').hidden=next!=='tour';$('g-source').hidden=true;
  nav.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.id==='g-'+next+'-tab')));$('g-title').textContent=next==='chat'?'Let’s talk.':next==='request'?'Connect with Taher':'Portfolio guide';mood('curious');if(next==='chat')$('g-question').focus();}
 $('g-tour-tab').onclick=()=>switchMode('tour');$('g-chat-tab').onclick=()=>switchMode('chat');$('g-request-tab').onclick=()=>switchMode('request');
 function addMessage(who,text){const p=document.createElement('p');p.className='g-message g-message-'+who;const label=document.createElement('strong');label.textContent=who==='user'?'You':'AI guide';const body=document.createElement('span');body.textContent=text;p.append(label,body);$('g-messages').append(p);p.scrollIntoView({block:'nearest'});return p;}
 async function call(payload,signal){if(!configured)throw Error('This copy of the portfolio is not connected yet. Please use the direct contact links.');const r=await fetch(config.url+'/functions/v1/portfolio-assistant',{method:'POST',headers:{'Content-Type':'application/json',apikey:config.key},body:JSON.stringify(payload),signal});let data;try{data=await r.json();}catch{throw Error('The service is unavailable. Please try again later.');}if(!r.ok)throw Error(data.error||'The service is unavailable. Please use the contact links.');return data;}
 $('g-chat-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const text=$('g-question').value.trim();if(!text)return;busy=true;controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),25000);$('g-send').disabled=true;$('g-cancel').hidden=false;$('g-chat-status').textContent='Checking the portfolio…';mood('curious');addMessage('user',text);$('g-question').value='';
  try{const data=await call({action:'chat',message:text,history:history.slice(-6)},controller.signal);if(typeof data.answer!=='string')throw Error('No answer was returned. Please try again.');addMessage('assistant',data.answer);history.push({role:'user',content:text},{role:'assistant',content:data.answer});history=history.slice(-6);const links=document.createElement('div');links.className='g-source-links';for(const s of data.sources||[]){if(!/^\/(?:skills\/)?#[\w-]+$|^\/skills\/$/.test(s.url))continue;const a=document.createElement('a');a.textContent=s.title+' ↗';a.href=s.url;links.append(a);}$('g-messages').append(links);$('g-chat-status').textContent='Want to reach Taher? Choose Leave a request.';mood('happy');}
  catch(err){$('g-chat-status').textContent=err.name==='AbortError'?'Stopped waiting. You can retry, take the tour, or leave a request.':err.message;mood('curious');}
  finally{clearTimeout(timeout);busy=false;controller=null;$('g-send').disabled=false;$('g-cancel').hidden=true;}
 };
 $('g-cancel').onclick=()=>controller?.abort();$('g-clear').onclick=()=>{controller?.abort();history=[];$('g-messages').replaceChildren();$('g-chat-status').textContent='Conversation cleared from this page.';};
 $('g-request-form').onsubmit=e=>{e.preventDefault();if(sending)return;review=Object.fromEntries(new FormData(e.target));requestID=crypto.randomUUID();$('g-review-text').replaceChildren();for(const k of ['name','email','category','subject','message']){const p=document.createElement('p');p.textContent=k+': '+review[k];$('g-review-text').append(p);}$('g-consent').checked=false;e.target.hidden=true;$('g-review').hidden=false;$('g-consent').focus();};
 $('g-edit').onclick=()=>{if(sending)return;$('g-review').hidden=true;$('g-request-form').hidden=false;review=null;requestID=null;};
 $('g-confirm').onclick=async()=>{if(sending||!review)return;if(!$('g-consent').checked){$('g-request-status').textContent='Please confirm that you want to send these details.';return;}sending=true;$('g-confirm').disabled=true;$('g-edit').disabled=true;$('g-request-status').textContent='Saving your request…';
  try{const r=await call({action:'request',...review,id:requestID,confirmed:true},AbortSignal.timeout(20000));if(r.id!==requestID)throw Error('No receipt was returned. Please retry.');$('g-request-status').textContent=r.message+' Reference: '+r.id.slice(0,8);$('g-review').hidden=true;$('g-request-form').reset();$('g-request-form').hidden=false;review=null;requestID=null;mood('happy');}
  catch(e){$('g-request-status').textContent=e.name==='TimeoutError'?'No receipt received. Retry safely using Confirm & send, or use direct email.':e.message;}
  finally{sending=false;$('g-confirm').disabled=false;$('g-edit').disabled=false;}
 };
 const cleanup=()=>{controller?.abort();stopSpeech();};$('g-minimize').addEventListener('click',cleanup);$('g-dismiss').addEventListener('click',cleanup);window.addEventListener('pagehide',cleanup);
 root.addEventListener('keydown',e=>{if(e.key==='Escape')cleanup();});
 $('g-launch').addEventListener('click',()=>{if(!panel.hidden&&mode!=='tour')switchMode(mode);});
 return {cancel:cleanup};
}
